108	// defaultBaseTransport returns the base HTTP transport.
109	// On App Engine, this is urlfetch.Transport.
110	// Otherwise, use a default transport, taking most defaults from
111	// http.DefaultTransport.
112	// If TLSCertificate is available, set TLSClientConfig as well.
113	func defaultBaseTransport(clientCertSource cert.Provider, dialTLSContext func(context.Context, string, string) (net.Conn, error)) http.RoundTripper {
114		defaultTransport, ok := http.DefaultTransport.(*http.Transport)
115		if !ok {
116			defaultTransport = transport.BaseTransport()
117		}
118		trans := defaultTransport.Clone()
119		trans.MaxIdleConnsPerHost = 100
120	
121		if clientCertSource != nil {
122			trans.TLSClientConfig = &tls.Config{
123				GetClientCertificate: clientCertSource,
124			}
125		}
126		if dialTLSContext != nil {
127			// If DialTLSContext is set, TLSClientConfig wil be ignored
128			trans.DialTLSContext = dialTLSContext
129		}
130	
131		// Configures the ReadIdleTimeout HTTP/2 option for the
132		// transport. This allows broken idle connections to be pruned more quickly,
133		// preventing the client from attempting to re-use connections that will no
134		// longer work.
135		http2Trans, err := http2.ConfigureTransports(trans)
136		if err == nil {
137			http2Trans.ReadIdleTimeout = time.Second * 31
138		}
139	
140		return trans
141	}
