			if remaining > 0 {
				if int64(n) > remaining {
					b.buf.Write(p[:remaining])
				} else {
					b.buf.Write(p[:n])
				}
			}
		}

		if err == io.EOF || int64(b.buf.Len()) >= maxErrorReadBytes {
